CREATE TYPE "wallet_type" AS ENUM ('CASH_ACCOUNT','CREDIT_CARD');
CREATE TYPE "category_type" AS ENUM ('INCOME','EXPENSE','BOTH');
CREATE TYPE "transaction_type" AS ENUM ('INCOME','EXPENSE','TRANSFER','CARD_PAYMENT');
CREATE TYPE "purchase_mode" AS ENUM ('CASH','INSTALLMENT_VALUE','TOTAL_VALUE');
CREATE TYPE "schedule_frequency" AS ENUM ('MONTHLY');
CREATE TYPE "schedule_status" AS ENUM ('PENDING','BILLED','CANCELLED','SKIPPED');
CREATE TABLE "wallets" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"user_id" text NOT NULL,"name" text NOT NULL,"type" wallet_type NOT NULL,"closing_day" integer,"due_day" integer,"active" boolean DEFAULT true NOT NULL,"created_at" timestamptz DEFAULT now() NOT NULL,"updated_at" timestamptz DEFAULT now() NOT NULL,CONSTRAINT "wallet_card_days" CHECK ((type='CASH_ACCOUNT' AND closing_day IS NULL AND due_day IS NULL) OR (type='CREDIT_CARD' AND closing_day BETWEEN 1 AND 31 AND due_day BETWEEN 1 AND 31)));
CREATE TABLE "categories" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"user_id" text NOT NULL,"name" text NOT NULL,"type" category_type DEFAULT 'BOTH' NOT NULL,"active" boolean DEFAULT true NOT NULL,"created_at" timestamptz DEFAULT now() NOT NULL,"updated_at" timestamptz DEFAULT now() NOT NULL);
CREATE TABLE "purchases" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"user_id" text NOT NULL,"description" text NOT NULL,"mode" purchase_mode NOT NULL,"total_amount_cents" bigint NOT NULL,"installment_total" integer DEFAULT 1 NOT NULL,"created_at" timestamptz DEFAULT now() NOT NULL,"updated_at" timestamptz DEFAULT now() NOT NULL,CONSTRAINT "purchase_positive" CHECK (total_amount_cents>0 AND installment_total>0));
CREATE TABLE "scheduled_rules" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"user_id" text NOT NULL,"description" text NOT NULL,"default_amount_cents" bigint NOT NULL,"type" transaction_type NOT NULL,"category_id" uuid REFERENCES categories(id),"frequency" schedule_frequency DEFAULT 'MONTHLY' NOT NULL,"start_competence" date NOT NULL,"end_competence" date,"active" boolean DEFAULT true NOT NULL,"created_at" timestamptz DEFAULT now() NOT NULL,"updated_at" timestamptz DEFAULT now() NOT NULL);
CREATE TABLE "scheduled_entries" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"user_id" text NOT NULL,"scheduled_rule_id" uuid NOT NULL REFERENCES scheduled_rules(id),"description" text NOT NULL,"expected_amount_cents" bigint NOT NULL,"competence" date NOT NULL,"status" schedule_status DEFAULT 'PENDING' NOT NULL,"billed_transaction_id" uuid,"created_at" timestamptz DEFAULT now() NOT NULL,"updated_at" timestamptz DEFAULT now() NOT NULL);
CREATE TABLE "transactions" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"user_id" text NOT NULL,"wallet_id" uuid NOT NULL REFERENCES wallets(id),"purchase_id" uuid REFERENCES purchases(id),"scheduled_entry_id" uuid REFERENCES scheduled_entries(id),"transfer_id" uuid,"description" text NOT NULL,"amount_cents" bigint NOT NULL,"type" transaction_type NOT NULL,"category_id" uuid REFERENCES categories(id),"consumption_date" date NOT NULL,"competence" date NOT NULL,"installment_number" integer,"installment_total" integer,"created_at" timestamptz DEFAULT now() NOT NULL,"updated_at" timestamptz DEFAULT now() NOT NULL,CONSTRAINT "transaction_non_zero" CHECK (amount_cents<>0),CONSTRAINT "transaction_installments" CHECK ((installment_number IS NULL AND installment_total IS NULL) OR installment_number BETWEEN 1 AND installment_total));
ALTER TABLE scheduled_entries ADD CONSTRAINT scheduled_entries_billed_transaction_fk FOREIGN KEY (billed_transaction_id) REFERENCES transactions(id) DEFERRABLE INITIALLY DEFERRED;
CREATE INDEX wallets_user_active_idx ON wallets(user_id,active); CREATE INDEX categories_user_active_idx ON categories(user_id,active); CREATE INDEX purchases_user_idx ON purchases(user_id); CREATE INDEX transactions_user_comp_idx ON transactions(user_id,competence); CREATE INDEX transactions_user_wallet_comp_idx ON transactions(user_id,wallet_id,competence); CREATE INDEX transactions_user_consumption_idx ON transactions(user_id,consumption_date); CREATE INDEX transactions_purchase_idx ON transactions(purchase_id); CREATE INDEX transactions_transfer_idx ON transactions(transfer_id); CREATE INDEX scheduled_rules_user_idx ON scheduled_rules(user_id); CREATE INDEX scheduled_entries_user_comp_status_idx ON scheduled_entries(user_id,competence,status); CREATE INDEX scheduled_entries_rule_idx ON scheduled_entries(scheduled_rule_id); CREATE UNIQUE INDEX scheduled_rule_comp_unique ON scheduled_entries(scheduled_rule_id,competence);
